changeSet.sql:
alter table employee_id_sequence add column if not exists java_format varchar(100);
update employee_id_sequence set java_format = 'F%04d' where workspace_id = 'KIM_LONG' and gender = 'FEMALE';
update employee_id_sequence set java_format = 'M%04d' where workspace_id = 'KIM_LONG' and gender = 'MALE';
update employee_id_sequence set java_format = 'F%04d' where workspace_id ='MMS' and  gender = 'FEMALE';
update employee_id_sequence set java_format = 'M%04d' where workspace_id ='MMS' and gender = 'MALE';

